using System;
using System.Collections.Generic;
using DenTinh.Core;
public static class ElementalTests {
    static int checks;
    static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
    static Simulation Game(){Simulation g=new Simulation(CatalogData.Create(),"thienvu",76119);g.Enemies.Clear();g.Props.Clear();g.Drops.Clear();g.Player.position=new V2(25,20);g.Player.crit=0;g.Tutorial=5;return g;}
    static EnemyState Dummy(Simulation g,V2 at){EnemyState e=g.Spawn("slime",at,false);e.hp=e.maxHp=100000;e.speed=e.damage=0;return e;}
    static void Tick(Simulation g,float seconds){for(int i=0;i<(int)Math.Ceiling(seconds/.02f);i++)g.Tick(.02f);}
    public static int Main(){try{
        ContentDatabase db=CatalogData.Create();Check(db.heroes.Length==4&&db.PlayableHeroes.Length==5&&db.elements.Length==7&&db.Weapon("prism").kind=="elemental","Original catalog preserved; Thiên Vũ and seven elements exported");
        Simulation g=Game();g.Input=new GameInput{move=new V2(-1,1),aim=new V2(40,20)};V2 before=g.Player.position;g.Tick(.02f);Check(g.Player.moveDir=="W"&&g.Player.position.x<before.x&&g.Player.position.y>before.y&&Math.Abs(g.Player.aimAngle)<.02,"Diagonal movement keeps both axes; horizontal body and aim independent");g.Input=new GameInput{aim=new V2(40,20)};g.Tick(.02f);Check(g.Player.moveDir=="W"&&!g.Player.moving,"Idle retains last body direction");g.Input=new GameInput{move=new V2(1,0),aim=new V2(10,20)};before=g.Player.position;g.Tick(.02f);Check(g.Player.position.x>before.x&&g.Player.moveDir=="E","Reversal responds within one tick");
        g=Game();EnemyState e=Dummy(g,new V2(28,20));e.type="archer";e.cooldown=0;e.speed=2;e.frozen=2;before=e.position;Tick(g,1.98f);Check(V2.Distance(e.position,before)<.001&&g.Bullets.Count==0,"Freeze blocks movement and attacks for full two seconds");Tick(g,.06f);Check(e.frozen==0&&g.Bullets.Count>0,"Freeze releases after two seconds");
        g=Game();e=Dummy(g,new V2(29,20));e.type="shade";e.speed=3;e.rooted=2.5f;e.cooldown=0;before=e.position;Tick(g,2.48f);Check(V2.Distance(e.position,before)<.001,"Root blocks walking and shade teleport for 2.5 seconds");Tick(g,.08f);Check(e.rooted==0&&V2.Distance(e.position,before)>.001,"Root releases movement");
        g=Game();e=Dummy(g,new V2(28,20));e.type="boss";e.frozen=2;e.cooldown=0;before=e.position;Tick(g,1.98f);Check(V2.Distance(e.position,before)<.001&&g.Bullets.Count==0&&g.Dangers.Count==0,"Boss freeze has same two second hard stop");
        foreach(ElementDef f in db.elements)foreach(string key in new[]{"q","e","r"}){g=Game();e=Dummy(g,new V2(27,20));g.CastElement(f.id,key,null,e.position);Tick(g,.9f);Check(e.hp<e.maxHp||g.Summons.Count>0||g.Player.hoverboard>0,f.id+" "+key+" performs combat behavior");}
        g=Game();e=Dummy(g,new V2(27,20));g.CastElement("earth","r",null,e.position);g.CastElement("nature","r",null,e.position);Check(g.Summons.Count==4&&g.Summons[0].maxLife==18&&g.Summons[1].maxLife==30,"Golem 18s and treants 30s lifetimes");Tick(g,18.04f);Check(g.Summons.Count==3,"Golem expires before treants");Tick(g,12);Check(g.Summons.Count==0,"Treants expire at 30s");
        g=Game();for(int i=0;i<5;i++)Dummy(g,new V2(28+i%2,19+i));Check(g.SplitElementals(7)&&g.Clones.Count==0,"Split waits for intro");Tick(g,4.2f);Check(g.Clones.Count==6,"Seven forms include player and six independent NPCs");g.Tick(.02f);HashSet<string> targets=new HashSet<string>();foreach(CloneState c in g.Clones)if(c.targetId!=null)targets.Add(c.targetId);Check(targets.Count>=3,"NPCs spread targets");CloneState wind=g.Clones.Find(c=>c.element=="wind");g.Dangers.Add(new Danger{position=wind.position,radius=1,time=1});g.Tick(.02f);Check(wind.aiState=="flank"&&wind.dashCd>0&&wind.velocity.Length>0,"NPC escapes exact danger center without zero vector");g.Dangers.Clear();g.Player.rCd=20;g.Player.mp=80;Tick(g,7);Check(Math.Abs(g.Player.rCd-13)<.03f&&g.Player.mp>=80&&g.Summons.Count>0,"NPC Q E R do not consume player mana or alter ultimate cooldown");
        g=Game();g.SplitElementals(7);Tick(g,4.2f);g.Clones[0].action=new ActorAction{key="r",elapsed=.2f};g.Clones[0].qCd=3.2f;Simulation restored=Simulation.Restore(db,g.Capture());Check(restored.Clones.Count==6&&restored.Clones[0].action==null&&restored.Clones[0].qCd==3.2f,"Save keeps NPC cooldowns, drops pending casts");
        g=Game();e=Dummy(g,new V2(28,20));g.CastElement("earth","q",null,e.position);g.TeleportPlayer(new V2(40,20));Tick(g,1);Check(e.hp==e.maxHp,"Teleport cancels delayed owned strikes");g.SplitElementals(7);g.CastElement("nature","r",null,new V2(42,20));g.Respawn();Check(g.Clones.Count==0&&g.Summons.Count==0&&g.ElementFields.Count==0,"Respawn clears combat entities");
        foreach(float crit in new[]{0f,1f}){g=Game();e=Dummy(g,new V2(28,20));g.Player.crit=crit;g.CastElement("light","q",null,e.position);Check(e.maxHp-e.hp==(float)Math.Round(g.Player.damage*3*1.7f)&&g.Effects.Exists(f=>f.kind=="text"&&f.text.EndsWith("!"))&&g.Player.crit==crit,"Light backstab guarantees one critical and restores crit "+crit);}
        g=Game();g.Player.position=g.Shrines[0].position;g.Shrines[0].active=true;g.SplitElementals(7);g.CastElement("nature","r",null,g.Player.position);Check(g.Interact()&&g.Clones.Count==0&&g.Summons.Count==0&&g.ElementFields.Count==0&&V2.Distance(g.Player.position,new V2(11.5f,10))<.01f,"Shrine travel clears owned combat entities");
        Console.WriteLine(checks+" elemental checks passed");return 0;
    }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
}
